-- =====================================================================
-- Wild Tuskers Sri Lanka — starter data
-- (the records that were previously hard-coded in src/models/*.js)
-- Run AFTER the migration. Safe to re-run: existing rows are skipped.
-- =====================================================================

-- Official WTS tusker list (Full_list.xlsx). Requires migration 20261114010000.
on conflict (id) do update set
  name = excluded.name,
  location = excluded.location,
  living_status = excluded.living_status,
  death_year = excluded.death_year,
  death_reason = excluded.death_reason,
  last_seen_area = excluded.last_seen_area,
  zone = excluded.zone,
  district = excluded.district,
  province = excluded.province,
  last_seen = excluded.last_seen,
  age_range = excluded.age_range,
  health_condition = excluded.health_condition,
  threat_level = excluded.threat_level,
  remarks = excluded.remarks;

-- Update photos, comparisons, and ear biometrics for verified field records
update public.tuskers 
set 
  photos = array['/tuskers/t075_kawanthissa.jpg'],
  ear_photos = array['/tuskers/kawanthissa_ear.jpg', '/tuskers/kawanthissa_ear.jpg', '/tuskers/kawanthissa_ear.jpg'],
  ear_comparison = '[
    {"year":"2017","stage":"Baseline Ear Biometrics","photo":"/tuskers/kawanthissa_ear.jpg","changeSentence":"Baseline ear documentation recording initial lobe curvature, natural folds, and healthy margin contours in Galgamuwa.","hasChange":false},
    {"year":"2021","stage":"Intermediate Biometric Progression","photo":"/tuskers/kawanthissa_ear.jpg","changeSentence":"Intermediate pinna comparison showing natural lobe growth with stable margin venation and diagnostic markings.","hasChange":false},
    {"year":"2026","stage":"Recent Biometric Record","photo":"/tuskers/kawanthissa_ear.jpg","changeSentence":"Verified ear margin profile and permanent lifetime biometric identification verified prior to demise.","hasChange":false}
  ]'::jsonb,
  photographic_comparison = '[
    {"year":"2017","stage":"First Recorded Photo","photo":"/tuskers/kawanthissa_comparison.jpg","changeSentence":"Baseline photographic documentation in Galgamuwa recording initial ivory alignment and undisturbed physical condition.","hasChange":false},
    {"year":"2021","stage":"4-Year Progression","photo":"/tuskers/kawanthissa_comparison.jpg","changeSentence":"Intermediate monitoring after 4 years showing distinctive cranial structure and verified facial traits.","hasChange":false},
    {"year":"2026","stage":"Final Assessment","photo":"/tuskers/kawanthissa_comparison.jpg","changeSentence":"Recent photographic progression before demise documented in Galgamuwa.","hasChange":false}
  ]'::jsonb
where id = 'T075';
